mapper.select:
select edu_course_package_exam.id as middleId,edu_course_package_exam.custom_exampaper_name as middleName,edu_course_package_exam.clazz_id as middleCourse
,exam_exampaper.*,edu_course.course_name as courseName,edu_course.course_name as clazz_name

    , (select count(1) from exam_exampaper_record where exam_exampaper_record.middle_id=edu_course_package_exam.id
    and exam_exampaper_record.user_id in

        #{item}
    ) as exam_num

from edu_course_package_exam
left join exam_exampaper on edu_course_package_exam.exampaper_id = exam_exampaper.id
left join edu_course on edu_course_package_exam.clazz_id = edu_course.id

    1=1

        and edu_course_package_exam.course_id = #{coursePackageExam.courseId}


        and exam_exampaper.name like concat('%',#{coursePackageExam.examName},'%')


        and exam_exampaper.type=#{coursePackageExam.examType}


        and edu_course_package_exam.clazz_id=#{coursePackageExam.clazzId}


        and edu_course_package_exam.course_id in

            #{item}



order by edu_course_package_exam.sort desc
